import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import java.math.BigInteger;
import java.nio.file.*;
import com.google.gson.*;
public class ADecomp extends GhidraScript {
 public void run() throws Exception {
  var args=getScriptArgs(); var out=new JsonArray(); var di=new DecompInterface(); di.openProgram(currentProgram);
  for(int k=1;k<args.length;k++) {
   boolean inside=args[k].startsWith("@"); var ad=toAddr(Long.decode(inside?args[k].substring(1):args[k])&~1L); var f=inside?getFunctionContaining(ad):getFunctionAt(ad);
   if(f==null) { var old=getFunctionContaining(ad); if(old!=null) removeFunction(old); clearListing(ad,ad.add(3)); currentProgram.getProgramContext().setValue(currentProgram.getRegister("TMode"),ad,ad,BigInteger.ONE); disassemble(ad); f=createFunction(ad,null); }
   var o=new JsonObject(); o.addProperty("entry",f==null?ad.toString():f.getEntryPoint().toString());
   if(f!=null) { var r=di.decompileFunction(f,90,monitor); o.addProperty("status",r.decompileCompleted()?"ok":"failed"); if(r.getDecompiledFunction()!=null)o.addProperty("pseudo_code",r.getDecompiledFunction().getC()); var listing=new StringBuilder(); var it=currentProgram.getListing().getInstructions(f.getBody(),true); while(it.hasNext()){var ins=it.next();listing.append(ins.getAddress()+" "+ins+"\n");}o.addProperty("listing",listing.toString()); }
   out.add(o);
  } di.dispose(); Files.writeString(Path.of(args[0]),out.toString());
 }
}

